import express from 'express';
import helmet from 'helmet';
import cookieParser from 'cookie-parser';
import {rateLimit} from 'express-rate-limit';
import multer from 'multer';
import {randomBytes,randomUUID,createHmac} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {Search,validateCertificate,readCertificate,findJobs} from './jobs.js';
import {AppError} from './errors.js';
export function createApp({providers,secret,origin,production=false,render=false,configured={ai:true,search:true}}){
 const app=express();const tasks=new Map();const active=new Set();
 app.disable('x-powered-by');if(render)app.set('trust proxy',1);
 app.use(helmet({contentSecurityPolicy:{directives:{defaultSrc:["'self'"],scriptSrc:["'self'"],styleSrc:["'self'"],imgSrc:["'self'",'blob:','data:'],objectSrc:["'none'"],frameAncestors:["'none'"],upgradeInsecureRequests:production?[]:null}}}));
 if(!production)app.use((_req,res,next)=>{res.removeHeader('Strict-Transport-Security');next();});
 app.use('/api',rateLimit({windowMs:900000,limit:180,standardHeaders:'draft-8',legacyHeaders:false}));
 app.use(cookieParser(secret));app.use(express.json({limit:'24kb'}));
 app.use('/api',(req,res,next)=>{res.set('Cache-Control','no-store');let session=req.signedCookies.cv_session;if(!/^[a-f0-9]{64}$/.test(session||'')){session=randomBytes(32).toString('hex');res.cookie('cv_session',session,{signed:true,httpOnly:true,secure:production,sameSite:'strict',path:'/',maxAge:86400000});}req.owner=createHmac('sha256',secret).update(session).digest('hex');req.csrf=createHmac('sha256',secret).update('csrf:'+session).digest('hex');if(!['GET','HEAD','OPTIONS'].includes(req.method)&&(req.get('origin')!==origin||req.get('x-csrf-token')!==req.csrf))return next(new AppError(403,'Sessão expirada. Atualize a página e tente novamente.'));next();});
 const expensive=rateLimit({windowMs:900000,limit:10,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Limite de consultas atingido. Aguarde alguns minutos.'}});
 const available=(req,_res,next)=>{if(!configured.ai||!configured.search)return next(new AppError(503,'As APIs do Gemini e Tavily ainda precisam ser configuradas no servidor.'));if(active.has(req.owner)||active.size>=3)return next(new AppError(429,'Aguarde a consulta atual terminar.'));next();};
 function launch(req,res,work){for(const [id,t]of tasks)if(Date.now()-t.created>1800000)tasks.delete(id);if(tasks.size>=100)throw new AppError(429,'O servidor está ocupado. Tente novamente em instantes.');const id=randomUUID();const task={id,owner:req.owner,created:Date.now(),status:'running',stage:'prepare'};tasks.set(id,task);active.add(req.owner);res.status(202).json({id});(async()=>{try{task.result=await work(async stage=>{task.stage=stage;});task.status='complete';}catch(e){task.status='failed';task.error=e instanceof AppError?e.message:'A consulta não terminou. Tente novamente, ou informe o curso manualmente.';}finally{active.delete(req.owner);}})();}
 app.get('/api/status',(req,res)=>res.json({csrfToken:req.csrf,...configured}));
 const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024,files:1,fields:1}});
 app.post('/api/certificate',expensive,available,upload.single('certificate'),async(req,res,next)=>{try{if(req.body.consent!=='true')throw new AppError(400,'Autorize a leitura do certificado para continuar.');const attachment=await validateCertificate(req.file);req.file=null;launch(req,res,async progress=>{await progress('certificate');return readCertificate(attachment,providers);});}catch(e){next(e);}});
 app.post('/api/search',expensive,available,(req,res,next)=>{try{const parsed=Search.safeParse(req.body);if(!parsed.success)throw new AppError(400,'Confira curso, cargos, cidade, estado e modalidade.');launch(req,res,progress=>findJobs(parsed.data,providers,progress));}catch(e){next(e);}});
 app.get('/api/tasks/:id',(req,res,next)=>{const t=tasks.get(req.params.id);if(!t||t.owner!==req.owner||Date.now()-t.created>1800000)return next(new AppError(404,'Consulta não encontrada ou expirada.'));res.json({id:t.id,status:t.status,stage:t.stage,...(t.status==='complete'?{result:t.result}:{}),...(t.status==='failed'?{error:t.error}:{})});});
 app.use('/api',(_req,_res,next)=>next(new AppError(404,'Rota não encontrada.')));
 app.use(express.static(fileURLToPath(new URL('../public',import.meta.url)),{dotfiles:'deny'}));
 app.use((e,_req,res,_next)=>res.status(e instanceof multer.MulterError?400:e.status||500).json({error:e instanceof multer.MulterError?'Envie um único arquivo PDF, JPG ou PNG de até 8 MB.':e instanceof AppError?e.message:'Serviço temporariamente indisponível.'}));
 return app;
}

